class TokenBucket {
    private final int capacity;
    private double tokens;
    private final double refillPerSecond;
    private long lastRefillNanos = System.nanoTime();

    TokenBucket(int capacity, double refillPerSecond) {
        this.capacity = capacity;
        this.tokens = capacity;
        this.refillPerSecond = refillPerSecond;
    }

    synchronized boolean tryConsume() {
        refill();
        if (tokens >= 1) { tokens -= 1; return true; }
        return false;
    }

    private void refill() {
        long now = System.nanoTime();
        double elapsedSeconds = (now - lastRefillNanos) / 1_000_000_000.0;
        tokens = Math.min(capacity, tokens + elapsedSeconds * refillPerSecond);
        lastRefillNanos = now;
    }
}

Map<String, TokenBucket> bucketsByClient = new ConcurrentHashMap<>();

server.createContext("/api/data", exchange -> {
    String clientId = exchange.getRequestHeaders().getFirst("X-Client-Id");
    TokenBucket bucket = bucketsByClient.computeIfAbsent(clientId, k -> new TokenBucket(5, 2.0));

    if (bucket.tryConsume()) {
        exchange.getResponseHeaders().add("X-RateLimit-Limit", "5");
        respond(exchange, 200, "{\"data\":\"...\"}");
    } else {
        exchange.getResponseHeaders().add("Retry-After", "1");
        exchange.sendResponseHeaders(429, -1); // KLIENT przekroczyl limit - kategoria 4xx (Lesson05)
    }
});

